command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/outbound-storage-drag-20261006"
$main="4f03ea8bc499cd8e4d064431753d4f7aefac0fff"
$p1="2d0d6c84ecfa2fa55239c7713ef709b1f2546360"
$candidate="0d23048d47b158b98c2aff0cf7f3ec5ffc8c5ebb"
$temp=Join-Path $env:RUNNER_TEMP ("outbound-storage-drag-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $main){throw "main moved before outbound-drag validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before outbound-drag validation: $branchSha"}
  & git merge-base --is-ancestor $p1 $candidate
  if($LASTEXITCODE -ne 0){throw "P2 candidate is not stacked on accepted P1"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $p1 $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & python -X utf8 tools\winui\check_python_static.py tests\winui\test_outbound_drag_contract.py tests\winui\test_outbound_drag_explorer_gui.py
  if($LASTEXITCODE -ne 0){throw "outbound drag Python static check failed"}

  & python -X utf8 -m unittest tests.winui.test_outbound_drag_contract tests.winui.test_transfer_budget_contract
  if($LASTEXITCODE -ne 0){throw "outbound drag source contracts failed"}

  & python -X utf8 tools\winui\run_checks.py fast --before $p1 --head $candidate
  if($LASTEXITCODE -ne 0){throw "P2 FAST validation failed"}

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "P2 Release build failed"}

  & python -X utf8 tools\winui\check_python_deps.py --gui
  if($LASTEXITCODE -ne 0){throw "GUI dependency check failed"}

  $env:FLY_MIGRATION_CONFIGURATION="Release"
  & python -X utf8 -u tests\winui\test_outbound_drag_explorer_gui.py
  if($LASTEXITCODE -ne 0){throw "physical outbound Explorer drag failed"}

  $env:FLY_M23_OWNED_FEATURES="YES"
  $env:FLY_M23_OWNED_DRAG_TEST="YES"
  $env:FLY_M23_OWNED_DRAG_TRACE="YES"
  & python -X utf8 -u tests\winui\test_shell_gui.py
  if($LASTEXITCODE -ne 0){throw "same-app physical drag regression failed"}

  Write-Host ("OUTBOUND_STORAGE_DRAG_CANDIDATE="+$candidate)
  Write-Host "OUTBOUND_STORAGE_DRAG_STANDARD=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
